                result = dfs(nr, nc, path + [(row, col)])
                grid[nr] = grid[nr][:nc] + '.' + grid[nr][nc+1:]
                if result:
                    return result
        return []

    if (start == goal and grid[start[0]][start[1]] == '.'):
