        (row, col), path = stack.pop()
        if (row, col) == goal:
            return [start] + path + [(row, col)]  # append the entire path
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if is_valid(nr, nc):
                stack.append(((nr, nc), path + [(row, col)]))
