    if start == goal or any(grid[x][start[1]] == '#' for x in range(len(grid))) or any(grid[start[0]][y] == '#' for y in range(len(grid[0]))):
        return [start] if all(grid[x][y] == '.' for x, y in [start]) else []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up
    revisited = set()

    def path_finder(x, y):
        if (x, y) == goal:
            return [(x, y)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < rows and 0 <= ny < cols and grid[nx][ny]!= '#' and (nx, ny) not in revisited):
                for n in path_finder(nx, ny):
                    yield [x, y] + n

    if (start[0], start[1]+1, start[0], start[1]-1, start[0]+1, start[0]-1) not in revisited:
        for path in path_finder(start[0], start[1]):
            yield path

    revisited.add((start[0], start[1]+1, start[0], start[1]-1, start[0]+1, start[0]-1))
    yield from solve(grid, (start[0]+1, start[1]), goal)  # right
    revisited.add((start[0], start[1]+1, start[0], start[1]-1, start[0]-1, start[0]+1))
    yield from solve(grid, (start[0]-1, start[1]), goal)  # left
    revisited.add((start[0]+1, start[1], start[0]-1, start[1], start[0]+1, start[0]-1))
    yield from solve(grid, (start[0], start[1]+1), goal)  # down
    revisited.add((start[0]-1, start[1], start[0]+1, start[1], start[0]-1, start[0]+1))
    yield from solve(grid, (start[0], start[1]-1), goal)  # up
