    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()

    def is_valid(i, j):
        return 0 <= i < M and 0 <= j < N and grid[i][j] == '.'

    def bfs():
        queue = deque([start])
        visited.add(start)
        while queue:
            i, j = queue.popleft()
            if (i, j) == goal:
                path = []
                while (i, j)!= start:
                    path.append((i, j))
                    e = (i + que[i][j], j + que[i][j])
                    i, j = e
                path.append(start)
                return list(reversed(path))
            for dx, dy in directions:
                x, y = i + dx, j + dy
                if is_valid(x, y) and (x, y) not in visited:
                    visited.add((x, y))
