def solve(nums, k):
    # Create a histogram of the frequencies of each number
    hist = {}
    for num in nums:
        if num in hist:
            hist[num] += 1
        else:
            hist[num] = 1

    # Generate a list of all numbers, repeated a number of times equal to their frequency
    repeated_nums = []
    for num, freq in hist.items():
        repeated_nums.extend([num] * freq)

    # Sort the list of numbers and select the k-th smallest one
    repeated_nums.sort()
    return repeated_nums[k - 1]
