import heapq

def solve(nums, k):
    """
    Returns the k-th smallest value in nums.
    """
    def get_frequencies(nums):
        """
        Returns a list of (number, frequency) pairs.
        """
        frequency_counter = {}
        for num in nums:
            frequency_counter[num] = frequency_counter.get(num, 0) + 1
        return sorted(frequency_counter.items())

    def calculate_normalized_frequency(number, total_values, frequency):
        """
        Normalizes the frequency so that numbers with the same frequency get equal weight.
        """
        total_frequencies = len(nums) // total_values
        return number / (total_values * total_frequencies) + frequency / total_values

    frequencies = get_frequencies(nums)
    total_values = len(nums)
    pq = []

    for number, frequency in frequencies:
        for _ in range(frequency):
            heapq.heappush(pq, calculate_normalized_frequency(number, total_values, frequency))

    for _ in range(total_values - len(pq)):
        heapq.heappop(pq)

    return heapq.nsmallest(k, pq)[-1] * total_values
