        min_val = nums[0]
        nums[0] = nums[n-1]
        nums[n-1] = None
        heapify(nums, n-1, 0)
        return min_val

    heapify_all(nums)
    for _ in range(k-1):
        _ = extract_min(nums)
    return extract_min(nums)
