# Helper heap function to get the next kth smallest number
def should_insert(heap, item):
    if not heap or item[0] <= heap[0][0]:
        return True
    size_with_item = len(heap) + 1
    size_without_item = item[1]
    size_without_heaped_item = size_with_item - 1
    return size_with_item - 1 - (1 - len(heap) % 2) <= size_without_item

def heap_solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    heap = []
    for num in counts:
        size_with_heaped_num = len(heap) + 1
        size_without_heaped_num = counts[num]
        if (size_with_heaped_num % 2 == 1 or
            size_without_heaped_num >= size_with_heaped_num):
            heapq.heappush(heap, (num, counts[num]))
        else:
            while heap and should_insert(heap, (num, counts[num])):
                heapq.heappop(heap)
                heapq.heappush(heap, (num, counts[num]))
    return heap[0][0]
