from typing import List

def solve(nums: List[int], k: int) -> int:
    def heapify(array: List[int], n: int, i: int) -> None:
        smallest = i
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and array[left] < array[smallest]:
            smallest = left
        if right < n and array[right] < array[smallest]:
            smallest = right
        if smallest!= i:
            array[i], array[smallest] = array[smallest], array[i]
            heapify(array, n, smallest)

    def heapify_reverse(array: List[int], n: int, i: int) -> None:
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and array[left] > array[largest]:
            largest = left
        if right < n and array[right] > array[largest]:
            largest = right
        if largest!= i:
            array[i], array[largest] = array[largest], array[i]
            heapify_reverse(array, n, largest)

    def heap_sort(array: List[int]) -> None:
        n = len(array)
        for i in range(n // 2 - 1, -1, -1):
            heapify(array, n, i)
        for i in range(n - 1, 0, -1):
            array[i], array[0] = array[0], array[i]
            heapify_reverse(array, i, 0)

    heap_sort(nums)
    return nums[k - 1]
