def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = deque([start])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def get_neighbours(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                yield r, c

    while queue:
        r, c = queue.popleft()
        if (r, c) == goal:
            path = []
            while (r, c)!= start:
                path.append((r, c))
                for nr, nc in get_neighbours(r, c):
                    if (nr, nc) == start:
                        path.append(start)
                        return path
                r, c = queue.popleft()
            path.append(start)
            return path[::-1]
        if (r, c) not in visited:
            visited.add((r, c))
            queue.extend(get_neighbours(r, c))
    return []
