        if (x, y) == goal:
            path = []
            while (x, y)!= start:
                path.append((x, y))
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = x + dx, y + dy
                    if (nx, ny) in visited and (nx, ny)!= (x + dx, y + dy):
                        path.append((nx, ny))
                        x, y = nx, ny
                        break
            path.append(start)
            path.reverse()
            return path
        if (x, y) not in visited:
            visited.add((x, y))
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                    stack.append((nx, ny))
    return []
