def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    walls = set((r, c) for r, row in enumerate(grid) for c, cell in enumerate(row) if cell == '#')

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and (r, c) not in walls

    def get_neighbors(cell):
        r, c = cell
        neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
        return [(r, c) for r, c in neighbors if is_valid(r, c)]

    def dfs(cell, path):
        if cell == goal:
            return [path + [cell]]
        path = path + [cell]
        neighbors = get_neighbors(cell)
        for neighbor in neighbors:
            if any(abs(x - y) > 1 for x, y in zip(cell, neighbor)):
                continue
            result = dfs(neighbor, path)
            if result:
                return result
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if start in walls or goal in walls:
        return []
    return dfs(start, []) or []
