    path = [start]

    if row == goal[0] and col == goal[1]:
        return path

    visited = set([start])
    stack = [(row, col)]

    while stack:
        r, c = stack.pop()
        for nr, nc in get_neighbours(grid, r, c, visited):
            if (nr, nc) == goal:
                visited.add((nr, nc))
                path.append((nr, nc))
                return path
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                stack.append((nr, nc))
                path.append((nr, nc))

