def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def neighbours(cell):
        row, col = cell
        paths = [
            (row - 1, col),
            (row + 1, col),
            (row, col - 1),
            (row, col + 1),
        ]
        return [path for path in paths if is_valid(*path)]

    start_col = start[1]
    start_row = start[0]

    if not is_valid(start_row, start_col) or start == goal:
        return [start]

    to_visit = [start]
    visited = set([start])

    while to_visit:
        current = to_visit.pop(0)

        for neighbour in neighbours(current):
            if neighbour == goal:
                path = [current, neighbour]
                while path[-2] in visited:
                    path.pop()
                return path
            elif neighbour not in visited:
                to_visit.append(neighbour)
                visited.add(neighbour)
                path = [current, neighbour]
                while path[-2] in visited:
                    path.pop()
                yield path

    yield []

def path_iteration(grid, start, goal):
    iterator = solve(grid, start, goal)

    def iterative_solutions():
        try:
            return next(iterator)
        except StopIteration:
            return []

    return iterative_solutions
