from typing import List, Tuple

def is_free(grid: List[str], row: int, col: int) -> bool:
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col]!= '#'

def get_neighbours(grid: List[str], row: int, col: int, visited: set) -> set:
    neighbours = set()
    if is_free(grid, row - 1, col): neighbours.add((row - 1, col))
    if is_free(grid, row + 1, col): neighbours.add((row + 1, col))
    if is_free(grid, row, col - 1): neighbours.add((row, col - 1))
    if is_free(grid, row, col + 1): neighbours.add((row, col + 1))
    return neighbours - visited

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    open_list = [start]
    closed_list = set()
    visited = set([start])

    while open_list:
        cell = open_list.pop(0)
        if cell == goal:
            return [start] + list(reversed([cell] + [cell for cell in open_list if cell not in closed_list]))

        for neighbour in get_neighbours(grid, *cell, visited):
            closed_list.add(cell)
            open_list.append(neighbour)
            visited.add(neighbour)

    return []
