def solve(grid, start, goal):
    """Finds a path between two cells of a grid."""
    def is_valid(row, col):
        """ Checks if a cell is within grid and not a wall. """
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col]!= '#'

    def get_neighbours(cell):
        """Gets all orthogonal neighbours of a cell."""
        r, c = cell
        return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]

    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    visited = set()

    def dfs(current, path):
        if current == goal:
            return [path + [current]]
        visited.add(current)
        for neighbour in get_neighbours(current):
            if is_valid(neighbour[0], neighbour[1]) and neighbour not in visited:
                for direction in directions:
                    dr, dc = directions[direction]
                    if neighbour[0] == current[0] + dr and neighbour[1] == current[1] + dc:
                        new_path = path + [current] if path else path
                        result = dfs(neighbour, new_path)
                        if result:
                            return result
        return []

    if grid[start[0]][start[1]] == '#' or (start == goal and grid[start[0]][start[1]] == '#'):
        return []
    return dfs(start, []) if start!= goal else [start]
