from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    def is_valid(r: int, c: int) -> bool:
        """Check if the cell at (r, c) is within the grid and not a wall."""
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c]!= '#'

    def neighbors(r: int, c: int) -> List[Tuple[int, int]]:
        """Get the 4 orthogonal neighbours of (r, c)."""
        return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]

    def explore(current: Tuple[int, int], visited: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        """Recursively explore paths from the current cell."""
        if current == goal:
            return [current]
        for neighbor in neighbors(*current):
            if is_valid(*neighbor) and neighbor not in visited:
                visited.append(neighbor)
                path = explore(neighbor, visited)
                if path:
                    path.insert(0, current)
                    return path
                visited.pop()
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not is_valid(*start) or not is_valid(*goal) or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    return explore(start, [start])
