        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbours(cell):
        row, col = cell
        return [
            (row - 1, col),
            (row + 1, col),
            (row, col - 1),
            (row, col + 1),
        ]

    directions = {
        (0, 1): (0, 0),  # right
        (0, -1): (0, 2),  # left
        (1, 0): (0, 3),  # down
        (-1, 0): (0, 1),  # up
    }

