        return []

    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        cell, path = queue.popleft()

        if cell == goal:
            return path

        for next_cell in get_neighbours(cell):
            if is_valid(next_cell[0], next_cell[1]) and next_cell not in visited:
                visited.add(next_cell)
                queue.append((next_cell, path + [next_cell]))

                if next_cell[0] == start[0]:
                    next_direction = 1 if next_cell[1] > start[1] else -1
                    next_index = 0 if next_cell[1] < start[1] else 1
                elif next_cell[1] == start[1]:
                    next_direction = 1 if next_cell[0] > start[0] else -1
                    next_index = 0 if next_cell[0] < start[0] else 1
                if next_cell == goal:
                    next_index = directions[directions[next_direction]].index(next_index)
                queue.append((next_cell, path + [
                    (start[0] + next_direction, start[1]),
                    (start[0], start[1]),
                    next_cell if next_cell[0]!= start[0] else None,
                    next_cell if next_cell[1]!= start[1] else None,
