        if valid(row - 1, col): queue.append(((row-1, col), path + [(row-1, col)]))
        if valid(row + 1, col): queue.append(((row+1, col), path + [(row+1, col)]))
        if valid(row, col - 1): queue.append(((row, col-1), path + [(row, col-1)]))
        if valid(row, col + 1): queue.append(((row, col+1), path + [(row, col+1)]))
    return []
