def solve(grid, start, goal):
    if len(grid) == 1 and start == goal:
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    que = [(start, [start])]
    visited = {(start[0], start[1]), }

    while que:
        (coord, path) = que.pop(0)
        for (dr, dc) in directions:
            r, c = coord[0] + dr, coord[1] + dc
            if (r, c) in visited or r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] == '#':
                continue
            if [r, c] == goal:
                return path + [(r, c)]
            visited.add((r, c))
            que.append(((r, c), path + [(r, c)]))

    return []
