def solve(grid, start, goal):
    n_rows = len(grid)
    n_cols = len(grid[0])
    dir_vecs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False for _ in range(n_cols)] for _ in range(n_rows)]

    def is_valid(row, col):
        return 0 <= row < n_rows and 0 <= col < n_cols and grid[row][col] == '.' and not visited[row][col]

    def neighbors(cell):
        row, col = cell
        for dr, dc in dir_vecs:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                yield (r, c)

    stack = [start]
    visited[start[0]][start[1]] = True
    while stack:
        path = []
        for row, col in stack:
            path.append((row, col))
            if (row, col) == goal:
                return path
            forneighbor in neighbors((row, col)):
                stack.append(neighbor)
                visited[neighbor[0]][neighbor[1]] = True
        stack.pop()

    return []

