def solve(grid, start, goal):
    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '."

    def neighbours(cell):
        x, y = cell
        return [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]

    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not grid[start[0]][start[1]].lower == '.'

    queue = deque([start])
    visited = {start}
    path = {}

    while queue:
        cell = queue.popleft()
        if cell == goal:
            route = []
            while cell in path:
                route.append(cell)
                cell = path[cell]
            return list(reversed(route))

        for neighbour in neighbours(cell):
            x, y = neighbour
            if is_valid(x, y) and neighbour not in visited:
                visited.add(neighbour)
                path[neighbour] = cell
                queue.append(neighbour)
    return []
