def solve_engine(grid, start, goal):
    queue = [(start, [start])]
    visited = set([start])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        (row, col), path = queue.pop(0)
        if (row, col) == goal:
            return path
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if (0 <= r < len(grid) and 0 <= c < len(grid[0]) and
                grid[r][c] == '.' and (r, c) not in visited):
                queue.append(((r, c), path + [(r, c)]))
                visited.add((r, c))
    return []

def is_valid_position(grid, row, col):
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col]!= '#'

def solve(grid, start, goal):
    if not is_valid_position(grid, start[0], start[1]) or not is_valid_position(grid, goal[0], goal[1]):
        return []
    return solve_engine(grid, start, goal) if start!= goal else [start]

