    que = deque([start])
    visited = set()

    while que:
        (row, col) = que.popleft()
        if (row, col) == goal:
            path = []
            while (row, col)!= start:
                path.appendleft((row, col))
                (row, col) = (row - (col - row < 0), col + (col - row > 0))
            path.appendleft(start)
