def solve(grid, start, goal):
    def is_valid_move(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def move_directions(pos):
        return [(pos[0]-1, pos[1]), (pos[0]+1, pos[1]), (pos[0], pos[1]-1), (pos[0], pos[1]+1)]

    def path_found(path, visited):  
        if path[-1] == goal:  
            return True 
        for i in range(len(path)-1):
            if is_valid_move(path[i][0]+1, path[i][1]+1) and path[i][0] < path[i+1][0] and visited[(path[i][0]+1, path[i][1]+1)] == False:  
                new_path = path[:i+1] + [(path[i][0]+1, path[i][1]+1)] + move_to_path((path[i][0]+1, path[i][1]+1), goal, visited, start)  
                if path_found(new_path, visited):
                    return True 
            elif is_valid_move(path[i][0]-1, path[i][1]-1) and path[i][0] > path[i+1][0] and visited[(path[i][0]-1, path[i][1]-1)] == False:  
                new_path = path[:i+1] + [(path[i][0]-1, path[i][1]-1)] + move_to_path((path[i][0]-1, path[i][1]-1), goal, visited, start)  
                if path_found(new_path, visited):
                    return True 
            elif is_valid_move(path[i][0], path[i][1]+1) and path[i][1] < path[i+1][1] and visited[(path[i][0], path[i][1]+1)] == False: 
                new_path = path[:i+1] + [(path[i][0], path[i][1]+1)] + move_to_path((path[i][0], path[i][1]+1), goal, visited, start) 
                if path_found(new_path, visited):
                    return True 
            elif is_valid_move(path[i][0], path[i][1]-1) and path[i][1] > path[i+1][1] and visited[(path[i][0], path[i][1]-1)] == False:
                new_path = path[:i+1] + [(path[i][0], path[i][1]-1)] + move_to_path((path[i][0], path[i][1]-1), goal, visited, start)
                if path_found(new_path, visited):
                    return True 

    def move_to_path(current, goal, visited = {}, current_path = []):  
        if (current in visited) and visited.get(current) == True: 
            return []  
        if current == goal: 
            return [current]
        visited.update({current: True})
        current_path.append(current)
        for i in move_directions(current):
            if not is_valid_move(i[0], i[1]):
                continue
            path = move_to_path(i, goal, visited, current_path)
            if path: 
                return [current] + path
        visited.pop(current)
        current_path.pop()
        return [] 

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    for i in move_directions(start):
        if start == start and start[0]+1 == i[0]  and start[1]+1 == i[1] and is_valid_move(start[0]+1, start[1]+1):  
            continue
        if is_valid_move(i[0], i[1]) and grid[i[0]][i[1]]!= '#':
            return move_to_path(i, goal)

    return []
