def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = {(start,)}

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c]!= '#'

    def explore(path, current):
        if current == goal:
            return [path + [current]]
        neighbours = [(r, c) for dr, dc in directions 
                      for r, c in zip(current, current) if is_valid(r + dr, c + dc) and
                      (r + dr, c + dc) not in visited and not dr and not dc]
        for r, c in neighbours:
            visited.add((r, c))
            result = explore(path + [current], (r, c))
            visited.remove((r, c))
            if result:
                return result
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    return explore([], start)

