    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()
    def is_valid(x: int, y: int) -> bool:
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def dfs(x: int, y: int, path: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        if (x, y) == goal:
            return path + [(x, y)]
        if (x, y) in visited:
            return []
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny): 
                result = dfs(nx, ny, path + [(x, y)])
                if result:
                    return result
        return []

    if len(grid) < 1 or len(grid[0]) < 1:
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#':
        return []
    return dfs(start[0], start[1], [])
