def is_valid(cell, rows, cols):
    """Check if a cell is within grid boundaries."""
    if 0 <= cell[0] < rows and 0 <= cell[1] < cols:
        return True
    return False

def is_free(cell, grid):
    """Check if a cell is free (not a wall)."""
    if grid[cell[0]][cell[1]]!= '#':
        return True
    return False

def dfs(grid, row, col, goal, path):
    """Depth-First Search to find a path."""
    # Check if the current cell is the goal
    if (row, col) == goal:
        return path + [(row, col)]

    # Mark the current cell as visited
    grid[row][col] = '#'

    # Try to move up, down, left, right
    directions = [(0, -1), (0, 1), (1, 0), (-1, 0)]
    for dr, dc in directions:
        r, c = row + dr, col + dc
        if is_valid((r, c), len(grid), len(grid[0])) and is_free((r, c), grid):
            new_path = dfs(grid, r, c, goal, path + [(row, col)])
            if new_path:
                return new_path

    # If no path is found, reset the current cell and return None
    grid[row][col] = '.'
    return None

def solve(grid, start, goal):
    """Find a path between two cells in a grid."""
    rows, cols = len(grid), len(grid[0])
    if not is_free(start, grid) or not is_free(goal, grid):
        return []

    if is_valid(start, rows, cols):
        return dfs(grid, start[0], start[1], goal, [])
    return []
