def in_bounds(grid: List[str], cell: Tuple[int, int]) -> bool:
    return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0])

def is_valid(grid: List[str], path: List[Tuple[int, int]]) -> bool:
    return (0 <= path[0]) and (path[0] < len(grid)) and (path) and (len(path)-1< len(grid[0])) and grid[path[-1][0]][path[-1][1]] == '.'

DIRECTIONS = [(0, 1), (0, -1), (1, 0), (-1, 0)]

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    visited = set()
    def dfs(current_path: List[Tuple[int, int]], current_cell: Tuple[int, int]) -> List[Tuple[int, int]]:
        if current_cell == goal:
            return current_path + [current_cell]
        visited.add(current_cell)
        path_to_return = None
        for dx, dy in DIRECTIONS:
            neighbor = (current_cell[0] + dx, current_cell[1] + dy)
            if in_bounds(grid, neighbor) and neighbor not in visited and is_valid(grid, current_path + [neighbor]) and grid[neighbor[0]][neighbor[1]] == '.':
                result = dfs(current_path + [neighbor],  neighbor)
                if result:
                    path_to_return = result
                    break
        return path_to_return
    grid_start = grid.copy()
    if grid[start[0]][start[1]]!= '.':
        return []
    grid[start[0]].grid[start[1]] = '#'
    if start == goal:
        visited.add(start)
        return [start]
    result = dfs([], start)
    return result
