from collections import deque

def solve(grid, start, goal):
    # helper function to check if a position is valid
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col]!= '#'

    # helper function to get neighbors
    def get_neighbors((row, col)):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            r, c = row + dr, col + dc
            if is_valid(r, c):
                yield (r, c)

    # helper function to mark a cell as visited
    def mark_visited(visited, (row, col)):
        visited.add((row, col))

    visited = set()
    to_visit = deque()
    path = None
    for i in count():
        for (row, col) in to_visit:
            for neighbor in get_neighbors((row, col)):
                if neighbor not in visited:
                    to_visit.append(neighbor)
                    visited.add(neighbor)
                    if neighbor == goal:
                        to_visit.clear()
                        path = [(row, col)]
                        current = neighbor
                        for _ in range(i):
                            current = path[-1]
                            for neighbor in reversed(list(get_neighbors(current))):
                                mark_visited(visited, neighbor)
                                if neighbor in visited:
                                    path.append(neighbor)
                                    break
                        path.extend(reversed(sorted(to_visit)))
                        path[-1] = goal
                        del path[i-1:]
        if not to_visit:
            break
        to_visit.clear()
        for row, col in product(range(len(grid)), range(len(grid[0]))):
            if is_valid(row, col) and grid[row][col] == '.':
                mark_visited(visited, (row, col))
                to_visit.append((row, col))
        if start in visited:
            path = [(r, c) for (r, c) in reversed(sorted(visited)) if (r, c) == goal]
            path[-1] = start

    return path or []
