def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]]!= '.' or grid[goal[0]][goal[1]]!= '.':
        return []

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    seen = set((start, start))

    def is_valid((row, col)):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbours(path):
        (last_row, last_col), path = path
        for dr, dc in directions:
            r, c = last_row + dr, last_col + dc
            path = [(r, c), path]
            if (r, c, (r, c)) in seen:
                seen.add((r+c, path))
                seen.remove((r+c-last_row-last_col+min(last_col+dc,r), [(last_row, last_col)]))
                continue
            if is_valid((r, c)):
                yield path
                continue
            if last_col+dc >= 0 and last_col+dc< len(grid[0]) - (last_row + dr > r):
                if (r+c, path) in seen:
                    continue
            seen.add((r+c-last_row-last_col+min(last_col+dc,r), path))

    def dfs(path):
        if path[-1] == goal:
            return path
        for next_path in get_neighbours(path):
            result = dfs(next_path)
            if result:
                return result
        return []

    return dfs([(start[0], start[1]), (start[0], start[1])]) [1:]
