                visited.add((ni, nj))
                stack.append(((ni, nj), path + [cell]))
                if backtrack(ni, nj, path + [cell]):
                    return True
                visited.remove((ni, nj))
                stack.pop()

        return False

    if backtrack(start[0], start[1], []):
        path = path + [(goal[0], goal[1])][path and path[-1]!= goal]

