def solve(grid, start, goal):
    def is_valid(x, y):
        """Return True if (x, y) is within grid boundaries and the cell is free."""
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def dfs(x, y):
        """Return all reachable cells from (x, y) in DFS."""
        reachable, visited = [(x, y)], set((x, y))
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            neighbours = ((cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1))
            for nx, ny in neighbours:
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    reachable.append((nx, ny))
                    visited.add((nx, ny))
                    stack.append((nx, ny))
        return reachable

    reachable_cells = dfs(start[0], start[1]) & dfs(goal[0], goal[1])
    if not reachable_cells or start not in reachable_cells or goal not in reachable_cells:
        return []

    def find_path(start, goal):
        """Return a path between two cells using Breadth-First Search."""
        queue = [[(start,)]]
        while queue:
            path = queue.pop(0)
            x, y = path[-1]
            if (x, y) == goal:
                return path
            neighbours = [((x, y-1),), ((x, y+1),), ((x-1, y),), ((x+1, y),)]
            for dx, dy in neighbours:
                nx, ny = dx
                if is_valid(nx, ny) and grid[nx][ny] == '.':
                    queue.append(path + [dx])

    start_index = [(x, y) for x, y in reachable_cells if (x, y) == start][0]
    goal_index = [(x, y) for x, y in reachable_cells if (x, y) == goal][0]
    return find_path(start_index, goal_index)

