def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    def valid(row, col):
        return (0 <= row < rows) and (0 <= col < cols) and grid[row][col]!= '#'

    directions = [(0, +1), (0, -1), (+1, 0), (-1, 0)]

    def explore(path, current, visited, queue):
        if (current == goal) or not visited:
            if (current == goal):
                visited.add(path[-1])
                queue.append(path + [current])
            return
        visited.add(current)
        for direction in directions:
            new_row, new_col = current[0] + direction[0], current[1] + direction[1]
            if valid(new_row, new_col) and (new_row, new_col) not in visited:
                explore(path + [current], (new_row, new_col), visited, queue)

    if not valid(start[0], start[1]) or grid[start[0]][start[1]] == '#':
        return []
    queue = [(start, [start])]
    explored = set([start])
    while queue:
        current, path = queue.pop(0)
        for direction in directions:
            new_row, new_col = current[0] + direction[0], current[1] + direction[1]
            if not explored:
                if valid(new_row, new_col) and (new_row, new_col) not in explored:
                    queue.append(((new_row, new_col), path + [current]))
                    explored.add((new_row, new_col))
            else:
                if valid(new_row, new_col) and (new_row, new_col) not in explored:
                    explore(path, (new_row, new_col), explored, queue)
    queue = [(goal, [path[-1] for path in queue if goal in path])]
    while queue:
        current, path = queue.pop(0)
        for direction in directions:
            new_row, new_col = current[0] + direction[0], current[1] + direction[1]
            if not any(i in path for i in [(new_row, new_col)]):
                path.insert(0,(new_row, new_col))
                queue.append(((new_row, new_col), sorted(path, reverse = True)))
    ans = [path for path in queue if path[0] == start][0]
    return [path for path in [(grid[i[0]][i[1]] for i in ans)] if path!= '#' or grid[i[0]][i[1]]!='#']
