        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny): 
                result = dfs(nx, ny, path + [(x, y)])
                if result:
                    return result
        return []

    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start]
    return dfs(*start, [])

