def is_valid(cell, rows, cols):
    """Check if a cell is within the grid."""
    if 0 <= cell[0] < rows and 0 <= cell[1] < cols:
        return True
    return False

def is_free(cell, grid):
    """Check if a cell is free from walls."""
    return grid[cell[0]][cell[1]] == '.'

def explore(grid, start, goal, path):
    """Explore all possible paths in the grid."""
    if path[-1] == goal:
        return [path]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    paths = []
    for d in directions:
        cell = (path[-1][0] + d[0], path[-1][1] + d[1])
        if is_valid(cell, len(grid), len(grid[0])) and is_free(cell, grid) and cell not in path:
            paths.extend(explore(grid, start, goal, path + [cell]))
    return paths

def solve(grid, start, goal):
    """Find a path between two cells of a grid."""
    if start == goal and is_free(start, grid):
        return [start]
    for c in grid:
        for r, char in enumerate(c):
            if (char == '#') or (r == start[1] and c == start[0]) or (r == goal[1] and c == goal[0]):
                return []
    return explore(grid, start, goal, [start])
