from typing import List, Tuple

def in_bounds(grid: List[str], point: Tuple[int, int]) -> bool:
    return 0 <= point[0] < len(grid) and 0 <= point[1] < len(grid[0])

def get_neighbours(grid: List[str], current: Tuple[int, int]) -> List[Tuple[int, int]]:
    neighbours = []
    for x, y in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
        new_point = (current[0] + x, current[1] + y)
        if in_bounds(grid, new_point) and grid[new_point[0]][new_point[1]]!= '#':
            neighbours.append(new_point)
    return neighbours

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    queue = [(start, [start])]
    visited = set()
    while queue:
        (x, y), path = queue.pop(0)
        if (x, y) == goal:
            return path
        path = list(path)
        path.append((x, y))
        for new_point in get_neighbours(grid, (x, y)):
            new_path = path + get_path(grid, visited, new_point)  
            if new_path[-1] == (new_point[0], new_point[1]):
                new_path.pop()
            if (new_point[0], new_point[1] not in visited):
                queue.append((new_point, new_path))
                visited.add((new_point[0], new_point[1]))
                visited.update(get_path(grid, visited, new_point))
    return []

def get_path(grid: List[str], visited: set, point: Tuple[int, int]) -> List[Tuple[int, int]]:
    return [p for p in visited if p!= (point[0], point[1])]
