    while queue:
        x, y = queue.popleft()
        path.append((x, y))

        if (x, y) == goal:
            break

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny]!= '#':
                queue.append((nx, ny))
                visited[nx][ny] = True

    result = path.copy()
    while path:
        if path[-1] not in [(x, y - 1), (x, y + 1), (x - 1, y), (x + 1, y), (x, y)]:

            if path[-1] == goal and len(result) > 1:
                result = result[:-1].copy()
                path = path[:-1].copy()
            else:
                return []
        else:
            path.pop()

    return result
