from collections import deque

def solve(grid, start, goal):
    # helper function to check if a position is valid
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    # helper function to get possible moves from a position
    def get_moves(row, col):
        moves = []
        for r, c in [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]:
            if is_valid(r, c):
                moves.append((r, c))
        return moves

    # helper function to perform BFS
    def breadth_first_search(frontier, path):
        queue = deque(frontier)
        visited = set(frontier)
        while queue:
            current = queue.popleft()
            if current == goal:
                path[current] = path[current.pop()]
                path.extend(path[current][::-1])
                return path
            for move in get_moves(*current):
                if move not in visited:
                    visited.add(move)
                    queue.append(move)
                    path[move] = path[current] + [move]
        return []

    # main function
    if start == goal and grid[start[0]][start[1]] == '.':
        path = [start]
    else:
        path = {start: [start]}
        frontier = get_moves(*start)
        if frontier:
            result = breadth_first_search(frontier, path)
            return result if result else None
    return path or []

