def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbours((row, col)):
        return [
            (row + 1, col) if is_valid(row + 1, col) else None,
            (row - 1, col) if is_valid(row - 1, col) else None,
            (row, col - 1) if is_valid(row, col - 1) else None,
            (row, col + 1) if is_valid(row, col + 1) else None
        ]

    if grid[start[0]][start[1]] in '#':
        return []
    if start == goal:
        return [start]

    stack = [start]
    visited = set()
    path = []

    path_lengths = {}
    current_path = None

    path_lengths[start] = 0
    while stack:
        (row, col) = stack.pop()
        if (row, col) == goal:
            current_path = path.copy()
            while (row, col)!= start:
                current_path.append(get_neighbours((row, col)).pop())
            break
        if (row, col) not in visited:
            visited.add((row, col))
            for n in get_neighbours((row, col)):
                if n not in visited:
                    stack.append((n[0],n[1]))
                    path_lengths[(n[0],n[1])] = path_lengths[(row, col)] + 1
                    path.append((n[0],n[1]))
    return current_path if current_path is not None else []
