            yield (r, (c,) + path[-2:])

    path = goal
    while (start, path[-2:]) not in seen:
        if path[1:]:
            seen.remove(path[-2:])
        path = [(x,y) for y in path for x in get_neighbours((y,x))]
    if (start, path[-2:]) not in seen:
        return []
    return list(reversed(path))[:-1]
