        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            xroot = self.find(x)
            yroot = self.find(y)
            if xroot == yroot:
                return False
            if self.rank[xroot] < self.rank[yroot]:
                self.parent[xroot] = yroot
            else:
                self.parent[yroot] = xroot
                if self.rank[xroot] == self.rank[yroot]:
                    self.rank[xroot] += 1
            return True

    uf = UnionFind(n)
    total_cost = 0
    edges = []
    for u, v, w in roads:
        edges.append((w, u, v))
    # Sort edges by weight
    edges.sort()
    for w, u, v in edges:
        if uf.union(u, v):
            total_cost += w
            if all(uf.find(i) == uf.find(0) for i in range(1, n)):
                break
    # Check if all cities are connected
    root = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root:
            return -1
    return total_cost
